// Output-only native controls: actual frozen backend seeds and archived immutable factors.
#include <karto_sdk/Mapper.h>
#include "solvers/ceres_solver.hpp"
#include <nlohmann/json.hpp>
#include <fstream>
#include <iostream>
#include <map>
#include <memory>
#include <stdexcept>
#include <iomanip>
using J=nlohmann::json;
using Solver=solver_plugins::CeresSolver;
void require(bool condition,const std::string&reason){if(!condition)throw std::runtime_error(reason);}
J pose(const karto::Pose2&p){return J::array({p.GetX(),p.GetY(),p.GetHeading()});}
J nodes(const karto::ScanSolver::IdPoseVector&p){J out=J::array();for(const auto&v:p)out.push_back({v.first,v.second.GetX(),v.second.GetY(),v.second.GetHeading()});return out;}
bool same(const karto::Pose2&a,const J&b){return a.GetX()==b.at(0).get<double>()&&a.GetY()==b.at(1).get<double>()&&a.GetHeading()==b.at(2).get<double>();}
J evaluation(const Solver::ObjectiveEvaluation&e){return {{"valid",e.valid},{"cost",e.cost},{"free_gradient_infinity_norm",e.free_gradient_infinity_norm},{"free_gradient_l2_norm",e.free_gradient_l2_norm},{"free_dimension",e.free_dimension}};}
int main(int argc,char**argv){if(argc!=4)return 2;rclcpp::init(argc,argv);try{
 std::ifstream input(argv[1]);J j;input>>j;const std::string profile=argv[2],output=argv[3];require(profile=="normal"||profile=="strict","undeclared profile");
 karto::Dataset dataset;dataset.LoadFromFile(j.at("archive_base").get<std::string>()+".data");for(auto*o:dataset.GetLasers())karto::SensorManager::GetInstance()->RegisterSensor(dynamic_cast<karto::Sensor*>(o));
 karto::Mapper archived;archived.LoadFromFile(j.at("archive_base").get<std::string>()+".posegraph");
 std::map<std::pair<int,int>,karto::LinkInfo*> labels;
 for(auto*edge:archived.GetGraph()->GetEdges())require(labels.emplace(std::make_pair(edge->GetSource()->GetObject()->GetUniqueId(),edge->GetTarget()->GetObject()->GetUniqueId()),dynamic_cast<karto::LinkInfo*>(edge->GetLabel())).second,"archive has duplicate directed endpoints");
 rclcpp::NodeOptions node_options;std::vector<rclcpp::Parameter> parameters;
 for(auto it=j.at("solver_parameters").begin();it!=j.at("solver_parameters").end();++it){if(it.value().is_string())parameters.emplace_back(it.key(),it.value().get<std::string>());else if(it.value().is_number_integer())parameters.emplace_back(it.key(),it.value().get<int>());else if(it.value().is_number_float())parameters.emplace_back(it.key(),it.value().get<double>());else if(it.value().is_boolean())parameters.emplace_back(it.key(),it.value().get<bool>());else throw std::invalid_argument("unsupported solver parameter");}
 parameters.emplace_back("ceres_diagnostics_path",output+".native.jsonl");parameters.emplace_back("ceres_diagnostics_state_mode","full");parameters.emplace_back("ceres_solver_profile","normal");node_options.parameter_overrides(parameters);
 auto node=std::make_shared<rclcpp::Node>("frozen_backend_control",node_options);node->declare_parameter("debug_logging",false);Solver solver;solver.Configure(node);
 std::map<int,std::unique_ptr<karto::LocalizedRangeScan>> scans;std::map<int,std::unique_ptr<karto::Vertex<karto::LocalizedRangeScan>>> vertices;std::vector<std::unique_ptr<karto::Edge<karto::LocalizedRangeScan>>> edges;
 for(const auto&row:j.at("nodes")){int id=row.at(0);auto scan=std::make_unique<karto::LocalizedRangeScan>(karto::Name("frozen_numeric_only"),karto::RangeReadingsVector{},karto::LocalizedRangeScan::LegacyRawTag{});scan->SetUniqueId(id);scan->SetCorrectedPose(karto::Pose2(row.at(1),row.at(2),row.at(3)));auto vertex=std::make_unique<karto::Vertex<karto::LocalizedRangeScan>>(scan.get());solver.AddNode(vertex.get());require(scans.emplace(id,std::move(scan)).second&&vertices.emplace(id,std::move(vertex)).second,"duplicate seed ID");}
 J binding=J::array();
 for(const auto&factor:j.at("factors")){const int source=factor.at("source_id"),target=factor.at("target_id");auto found=labels.find({source,target});require(found!=labels.end()&&found->second,"factor absent from archive");auto*label=found->second;require(same(label->GetPoseDifference(),factor.at("measurement_base_i")),"archive/frozen mean mismatch");for(int a=0;a<3;++a)for(int b=0;b<3;++b)require(label->GetCovariance()(a,b)==factor.at("covariance_base_i_row_major").at(3*a+b).get<double>(),"archive/frozen covariance mismatch");require(label->GetMeasurementIdentity()==factor.at("measurement_context").get<std::string>(),"archive/frozen owner context mismatch");if(factor.contains("raw_sources"))require(J(label->GetEvidence().raw_sources)==factor.at("raw_sources"),"archive/frozen raw evidence mismatch");
 auto edge=std::make_unique<karto::Edge<karto::LocalizedRangeScan>>(vertices.at(source).get(),vertices.at(target).get());edge->SetLabel(new karto::LinkInfo(*label));solver.AddConstraint(edge.get());binding.push_back({{"source_id",source},{"target_id",target},{"archived_context",label->GetMeasurementIdentity()},{"archived_view_count",label->GetEvidence().views.size()},{"known_evidence",label->GetEvidence().known()}});edges.push_back(std::move(edge));}
 auto before=solver.GetBackendSnapshot();require(before.known&&!before.transaction_active&&before.nodes.size()==j.at("nodes").size()&&before.constraints.size()==j.at("factors").size(),"incomplete native snapshot");require(before.anchor_valid&&before.anchor_id==j.at("anchor_id").get<int>()&&same(before.anchor_pose,j.at("anchor_pose")),"actual frozen anchor mismatch");require(nodes(before.nodes)==j.at("nodes"),"native seed differs from actual backend warm seed");
 auto prepared=solver.PrepareSolve(profile);require(bool(prepared),"no prepared candidate");const auto restored=solver.GetBackendSnapshot();require(nodes(restored.nodes)==nodes(before.nodes)&&restored.registration_id_watermark==before.registration_id_watermark,"prepare did not restore frozen warm seed");const auto result=solver.GetLastSolveResult();J iterations=J::array();for(const auto&i:result.native_summary.iterations)iterations.push_back({{"iteration",i.iteration},{"step_valid",i.step_is_valid},{"step_successful",i.step_is_successful},{"cost",i.cost},{"cost_change",i.cost_change},{"gradient_max_norm",i.gradient_max_norm},{"gradient_norm",i.gradient_norm},{"step_norm",i.step_norm},{"relative_decrease",i.relative_decrease},{"trust_region_radius",i.trust_region_radius},{"linear_solver_iterations",i.linear_solver_iterations}});
 bool finalized=false;if(prepared->numerical_accepted)finalized=solver.CommitPrepared(prepared)&&solver.FinalizePrepared(prepared);if(!finalized)require(solver.AbortPrepared(prepared),"control abort failed");auto final=solver.GetBackendSnapshot();
 J out={{"passed",true},{"input",argv[1]},{"arm",j.at("arm")},{"snapshot",j.at("snapshot")},{"profile",profile},{"initialization","actual_backend_warm_seed"},{"implicit_archive_solves",0},{"archive_pose_used_as_seed",false},{"factor_payload_source","matched original d87 LinkInfo immutable evidence; archive numeric measurements and owner context checked against frozen event inputs"},{"before_nodes",nodes(before.nodes)},{"candidate_nodes",nodes(prepared->candidate)},{"final_backend_nodes",nodes(final.nodes)},{"anchor_id",before.anchor_id},{"anchor_pose",pose(before.anchor_pose)},{"objective_model",before.objective_model},{"configured_options",before.solver_options},{"resolved_solve_options",prepared->solver_options},{"factor_count",before.constraints.size()},{"factor_archive_binding",binding},{"before",evaluation(result.before)},{"candidate",evaluation(result.candidate)},{"restored_backend",evaluation(result.committed)},{"numerical_accepted",prepared->numerical_accepted},{"native_attempted",result.attempted},{"decision",prepared->decision},{"backend_finalized",finalized},{"gradient_tolerance_met",prepared->gradient_tolerance_met},{"successful_noninitial_steps",prepared->successful_steps},{"iterations",iterations},{"summary",{{"usable",result.native_summary.IsSolutionUsable()},{"termination_type",int(result.native_summary.termination_type)},{"message",result.native_summary.message},{"initial_cost",result.native_summary.initial_cost},{"final_cost",result.native_summary.final_cost},{"num_successful_steps_including_iteration_zero",result.native_summary.num_successful_steps},{"num_unsuccessful_steps",result.native_summary.num_unsuccessful_steps},{"full_report",result.native_summary.FullReport()}}}};
 std::ofstream stream(output);stream<<std::setprecision(17)<<out.dump(2)<<'\n';stream.close();std::cout<<"{\"passed\":true,\"profile\":\""<<profile<<"\",\"nodes\":"<<before.nodes.size()<<",\"factors\":"<<before.constraints.size()<<",\"numeric_accepted\":"<<(prepared->numerical_accepted?"true":"false")<<"}\n";
 }catch(const karto::Exception&e){std::cerr<<e.GetErrorMessage()<<'\n';rclcpp::shutdown();return 1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';rclcpp::shutdown();return 1;}rclcpp::shutdown();return 0;}
